# frozen_string_literal: true

require "test_helper"

# the busyyaks yak hauls task cards — still artwork for the login page and the favicon, an animated one for
# the header that does one short work burst a minute (CSS inside the SVG, so it runs in an <img>): a backlog heap pops
# up in front of it and it plows the heap away. Generated by
# scripts/logo/build.py; never edit the SVGs by hand.
class LogoTest < Minitest::Test
  STATIC = File.expand_path("../../public/static", __dir__)
  read = ->(f) { File.read(File.join(STATIC, f)) }
  define_method(:svg) { |f| read.(f) }

  def test_animated_logos_burst_once_a_minute_and_respect_reduced_motion
    %w[logo-light-animated.svg logo-dark-animated.svg].each do |f|
      s = svg(f)
      assert_match(/@keyframes leg-a/, s, f)
      animations = s.scan(/animation:[\w-]+ ([\d.]+)s/).flatten.uniq
      assert_equal ["60"], animations, "#{f}: every part shares the one 60 s cycle"
      assert_includes s, "@media (prefers-reduced-motion:reduce){*{animation:none!important}.dust,.pile{display:none}}"
      (1..5).each { |k| assert_match(/@keyframes pile-#{k}\{/, s, "#{f}: backlog tile #{k} is plowed") }
      refute_match(/<script/i, s)
    end
  end

  def test_still_logos_and_icon_do_not_move
    %w[logo-light.svg logo-dark.svg icon.svg].each do |f|
      s = svg(f)
      refute_match(/@keyframes|animation:|class="pile|class="dust/, s, f)
      assert_includes s, 'class="load load-3"', "#{f}: the yak carries its cards"
    end
  end

  def test_header_uses_the_animated_logo_login_the_still_one
    root = File.expand_path("../..", __dir__)
    spa = File.read(File.join(root, "frontend/src/components/Layout.tsx"))
    %w[light dark].each { |s| assert_includes spa, "/static/logo-#{s}-animated.svg" }
    login = File.read(File.join(root, "app/templates/login.html.erb"))
    %w[light dark].each { |s| assert_includes login, %(h.asset("/static/logo-#{s}.svg")) }
  end
end
